        raw: HighwayReference.Nothrow.negatedMultiplyAddingWhereF16(
            mask.raw,
            a.raw,
            b.raw,
            SIMD<Float16>(
                raw: HighwayReference.Nothrow.repeatingF16(Float16(bitPattern: 26).bitPattern)
            ).raw
        )
    )
}
#endif
